// Find Due Diligence tasks that need processing
const tasks = $input.first().json.result || [];
console.log(`Checking ${tasks.length} tasks for Due Diligence processing`);

// Look for tasks with "Due Diligence:" in title
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Check if it's a Due Diligence task
  if (title.toLowerCase().includes('due diligence:')) {
    // Extract company name from title
    const companyName = title.replace(/due diligence:\s*/i, '').trim();

    // Check if Due Diligence is already completely done
    if (description.includes('🤖 COMPLETE DUE DILIGENCE REPORT GENERATED')) {
      console.log(`Task ${task.id} already has complete Due Diligence - skipping`);
      continue;
    }

    // Get all section names that are already approved
    const approvedSectionMatches = description.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/g) || [];
    const approvedSectionNames = approvedSectionMatches.map(match => {
      const nameMatch = match.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/);
      return nameMatch ? nameMatch[1] : '';
    });

    console.log(`Task ${task.id}: ${approvedSectionNames.length}/15 sections completed`);
    console.log(`Approved sections: ${approvedSectionNames.join(', ')}`);

    // Define all sections in order
    const allSections = [
      "Executive Summary", "Company Overview", "Business Model Analysis",
      "Market Analysis", "Financial Performance", "Management Team",
      "Technology Assessment", "Operations Analysis", "Legal and Compliance",
      "Risk Assessment", "ESG Analysis", "Competitive Landscape",
      "Growth Prospects", "Valuation Analysis", "Investment Recommendation"
    ];

    // Find NEXT section to process (must be sequential)
    let nextSectionToProcess = null;
    let nextSectionIndex = -1;

    // Find the first section that hasn't been approved yet
    for (let i = 0; i < allSections.length; i++) {
      if (!approvedSectionNames.includes(allSections[i])) {
        nextSectionToProcess = allSections[i];
        nextSectionIndex = i;
        break;
      }
    }

    // If we found a section that needs processing
    if (nextSectionToProcess) {
      console.log(`✅ Found Due Diligence task needing processing: "${title}" (ID: ${task.id})`);
      console.log(`Processing section: ${nextSectionToProcess} (${nextSectionIndex + 1}/15)`);

      return {
        json: {
          task_id: task.id,
          title: title.trim(),
          company_name: companyName,
          description: description.trim(),
          project_id: task.project_id || 1,
          current_section_number: nextSectionIndex,
          next_section_name: nextSectionToProcess,
          completed_sections: approvedSectionNames.length,
          approved_section_names: approvedSectionNames,
          all_sections: allSections
        }
      };
    } else {
      // All sections done, ready for final report generation
      console.log(`✅ All sections completed for task ${task.id}, creating final report`);
      return {
        json: {
          task_id: task.id,
          title: title.trim(),
          company_name: companyName,
          description: description.trim(),
          project_id: task.project_id || 1,
          current_section_number: 15,
          completed_sections: 15,
          ready_for_final_report: true,
          all_sections: allSections,
          approved_section_names: approvedSectionNames
        }
      };
    }
  }
}

// If no tasks need processing, stop gracefully
console.log('ℹ️ No Due Diligence tasks need processing - workflow completed');
throw new Error('No Due Diligence tasks need processing - workflow completed successfully');

